      <div class="ct-lib">${[...CT_인계물품,...list.map(o=>o.n).filter(n=>!CT_인계물품.includes(n))].map(n=>`<button type="button" class="chip${이름들.has(n)?" on":""}" data-act="cte-item" data-v="${esc(n)}" aria-pressed="${이름들.has(n)}">${esc(n)}</button>`).join("")}</div>
